namespace Scheduling;

/// <summary>Places jobs onto the most suitable available resource.</summary>
public sealed class Scheduler
{
    public IReadOnlyList<string> PlaceJobs(IEnumerable<Job> jobs, IReadOnlyList<Resource> resources)
    {
        var placements = new List<string>();
        foreach (var job in jobs)
        {
            if (!string.IsNullOrEmpty(job.RequiredSkill))
                placements.Add(CreatePlacement(job, resources));
        }

        return placements;
    }

    private static string CreatePlacement(Job job, IReadOnlyList<Resource> resources)
    {
        var chosen = FindBestResource(job.RequiredSkill, resources);
        if (chosen is null)
            return $"{job.Id}:UNPLACED";

        if (RequiresOvertime(job, chosen))
            return $"{job.Id}:{chosen.Name}:OT";

        return job.Priority > 8
            ? $"{job.Id}:{chosen.Name}:URGENT"
            : $"{job.Id}:{chosen.Name}";
    }

    private static Resource? FindBestResource(
        string requiredSkill,
        IReadOnlyList<Resource> resources)
    {
        Resource? chosen = null;
        foreach (var resource in resources)
        {
            if (!resource.Skills.Contains(requiredSkill) || resource.Calendar.Count > 20)
                continue;

            if (chosen is null || resource.Calendar.Count < chosen.Calendar.Count)
                chosen = resource;
        }

        return chosen;
    }

    private static bool RequiresOvertime(Job job, Resource resource) =>
        (job.Priority > 5 && resource.Calendar.Count > 10) ||
        job.Duration.TotalHours > 8;
}
